'use client';

import { useEffect, useId, useMemo, useRef, useState } from 'react';

import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import {
  pressedSolidOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { PlayIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { Canvas } from './canvas';
import {
  nodeOf,
  NODES,
  PIPELINE_NAME,
  PORT_TYPES,
  TYPE_WORD,
  type NodeId,
  type PortType,
} from './data';
import { layoutOf, type Orientation } from './layout';
import {
  INITIAL,
  isRunning,
  LOOP_AFTER_MS,
  phaseOf,
  reducer,
  RESTING,
  SCRIPT,
  type GraphState,
  type RunStatus,
} from './session';
import { useIsPhone } from './use-is-phone';
import { typeColorOf } from './wires';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
  holdWhile: isRunning,
};

const RUN_LABELS: Record<MorphState, string> = {
  idle: 'Run pipeline',
  busy: 'Running',
  done: 'Run pipeline',
};

/** How long a refused wire and its reason stay before they leave on their own. */
const REFUSAL_MS = 2400;

const CANVAS_HINT =
  'Drag from the port on the way out of a node to another node to connect them. The port on the way in of a node opens the list of nodes that can feed it. A wire only joins two ports of the same type.';

function orientationOf(isPhone: boolean | null): Orientation {
  if (isPhone) {
    return 'down';
  }
  return 'across';
}

function morphOf(isBusy: boolean): MorphState {
  if (isBusy) {
    return 'busy';
  }
  return 'idle';
}

function titleOf(id: NodeId | null) {
  if (id === null) {
    return null;
  }
  return nodeOf(id).title;
}

function countOf(state: GraphState, status: RunStatus) {
  const matching = NODES.filter(
    (node) => state.runs[node.id].status === status
  );
  return matching.length;
}

function ranWordOf(count: number) {
  if (count === 1) {
    return '1 node ran';
  }
  return `${count} nodes ran`;
}

/** The last run in one line: what ran, what came from cache, what was left out. */
function runLineOf(state: GraphState, runningTitle: string | null) {
  if (runningTitle !== null) {
    return `Running ${runningTitle}`;
  }
  const failed = NODES.find((node) => state.runs[node.id].status === 'failed');
  const skipped = countOf(state, 'skipped');
  if (failed) {
    return `${failed.title} failed, ${skipped} skipped`;
  }
  const done = countOf(state, 'done');
  const cached = countOf(state, 'cached');
  const hasRun = done + cached + skipped > 0;
  if (!hasRun) {
    return 'Not run yet';
  }
  const parts = [ranWordOf(done)];
  if (cached > 0) {
    parts.push(`${cached} from cache`);
  }
  if (skipped > 0) {
    parts.push(`${skipped} skipped`);
  }
  return parts.join(', ');
}

function LegendEntry({ type }: { type: PortType }) {
  return (
    <li className='flex items-center gap-1.5'>
      <span
        aria-hidden='true'
        style={{ backgroundColor: typeColorOf(type) }}
        className='h-0.5 w-4 rounded-full'
      />
      {TYPE_WORD[type]}
    </li>
  );
}

function Legend() {
  return (
    <ul
      aria-label='What each wire carries'
      className='text-muted-foreground flex flex-wrap items-center gap-x-4 gap-y-1 text-xs'
    >
      {PORT_TYPES.map((type) => (
        <LegendEntry key={type} type={type} />
      ))}
    </ul>
  );
}

export default function Workflows02() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const cellRef = useRef<HTMLDivElement>(null);
  const isPhone = useIsPhone(cellRef);
  const isVisible = useDocumentVisible();
  const isOnScreen = isInView && isVisible;
  const hintId = useId();
  const [round, setRound] = useState(0);
  const orientation = orientationOf(isPhone);
  const layout = useMemo(
    () => layoutOf(state.wires, orientation),
    [state.wires, orientation]
  );
  const phase = phaseOf(state);
  const phaseId = phase?.id ?? null;
  const phaseMs = phase?.ms ?? null;
  const phaseToken = phase?.token ?? null;
  const refusedId = state.refused?.id ?? null;
  const isBusy = phase !== null;
  const runningTitle = titleOf(phaseId);
  const runLine = runLineOf(state, runningTitle);
  const canReplay = isFinished && !isAutoplaying;
  const message = spokenUnless(isAutoplaying, state.notice);

  /**
   * A run holds its place off screen and in a hidden tab, as the session does: the node it is on
   * starts over on return.
   */
  useEffect(() => {
    const isIdle = phaseMs === null || phaseToken === null;
    if (isIdle || !isOnScreen) {
      return;
    }
    const end = () => act({ type: 'phaseEnded', token: phaseToken });
    const timer = setTimeout(end, phaseMs);
    return () => clearTimeout(timer);
  }, [act, isOnScreen, phaseId, phaseMs, phaseToken]);

  useEffect(() => {
    if (refusedId === null || !isOnScreen) {
      return;
    }
    const clear = () => act({ type: 'refusalCleared', id: refusedId });
    const timer = setTimeout(clear, REFUSAL_MS);
    return () => clearTimeout(timer);
  }, [act, isOnScreen, refusedId]);

  function run() {
    act({ type: 'ran' });
  }

  /** A new round starts on a fresh canvas, so the view a person left does not hide the demonstration. */
  function replay() {
    restart();
    setRound((current) => current + 1);
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container flex h-dvh min-h-[38rem] w-full flex-col overflow-hidden'
      >
        <div className='mx-auto flex min-h-0 w-full max-w-7xl flex-1 flex-col gap-3 p-3 @3xl:gap-4 @3xl:p-4'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
              <h1 className='truncate text-lg font-semibold'>
                {PIPELINE_NAME}
              </h1>
              <p className='text-muted-foreground flex flex-wrap items-center gap-x-2 gap-y-1 text-xs tabular-nums'>
                <Swap swapKey={runLine}>{runLine}</Swap>
                <Badge variant='secondary'>Illustrative</Badge>
              </p>
            </div>
            <div className='flex flex-wrap items-center gap-x-3 gap-y-2'>
              <ReplayButton
                isShown={canReplay}
                onReplay={replay}
                label='Replay the demo'
              />
              <MorphButton
                type='button'
                state={morphOf(isBusy)}
                labels={RUN_LABELS}
                idleIcon={<PlayIcon />}
                onClick={run}
                className={pressedSolidOf(pressed === 'run')}
              />
            </div>
          </header>

          <div
            ref={cellRef}
            className='group/canvas bg-foreground/[0.03] relative min-h-0 flex-1 overflow-hidden rounded-xl'
          >
            <Canvas
              key={round}
              isLaidOut={isPhone !== null}
              label={`Canvas of ${PIPELINE_NAME}`}
              subject='the pipeline'
              hintId={hintId}
              layout={layout}
              orientation={orientation}
              wires={state.wires}
              params={state.params}
              runs={state.runs}
              runningId={phaseId}
              wiring={state.wiring}
              refused={state.refused}
              isDemonstrating={isAutoplaying}
              pressed={pressed}
              onAction={act}
              onRun={run}
            />
            <p id={hintId} className='sr-only'>
              {CANVAS_HINT}
            </p>
          </div>

          <Legend />
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useLayoutEffect, useRef, useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

import { nodeIdOf, nodeOf, NODES, type NodeId, type Params } from './data';
import {
  nodeAt,
  wirePathOf,
  type GraphLayout,
  type Orientation,
  type Point,
} from './layout';
import { NodeCard, type Aim } from './node-card';
import { refusalOf, signatureOf, sourceOf } from './pipeline';
import type { GraphAction, NodeRun, Refused, Wire, Wiring } from './session';
import { usePanZoom } from './use-pan-zoom';
import {
  HeldLayer,
  typeColorOf,
  WireLayer,
  type HeldWire,
  type RefusedWire,
} from './wires';
import { ZoomControl } from './zoom-control';

type Wired = {
  kind: 'wire';
  pointerId: number;
  from: NodeId;
  aim: NodeId | null;
};

/** What the pointers on the canvas are doing: moving the view, or holding a wire out of a port. */
type Gesture = { kind: 'pan' } | Wired;

/** A wire lands on a node from this far around it. */
const AIM_REACH = 12;

const FRAME = [
  'absolute inset-0 cursor-grab overflow-hidden rounded-xl outline-none select-none active:cursor-grabbing',
  'group-focus-within/canvas:touch-none',
].join(' ');

/** A held wire only lives while something holds it: a pointer, or the demonstration. */
function heldWiringOf(isHeld: boolean, wiring: Wiring | null) {
  if (isHeld) {
    return wiring;
  }
  return null;
}

function aimOf(held: Wiring | null, wires: Wire[], id: NodeId): Aim {
  if (!held) {
    return 'idle';
  }
  if (held.from === id) {
    return 'source';
  }
  const canTake = refusalOf(wires, held.from, id) === null;
  const isUnder = held.to === id;
  if (isUnder && canTake) {
    return 'aimed';
  }
  if (isUnder) {
    return 'refusing';
  }
  if (canTake) {
    return 'open';
  }
  return 'closed';
}

/** The demonstration has no pointer, so its wire is drawn from its port to the node it aims at. */
function demoWireOf(
  held: Wiring | null,
  layout: GraphLayout<Wire>,
  orientation: Orientation
): HeldWire | null {
  if (!held || held.to === null) {
    return null;
  }
  const from = layout.places[held.from].output;
  const to = layout.places[held.to].input;
  if (!to) {
    return null;
  }
  return {
    path: wirePathOf(from, to, orientation),
    type: nodeOf(held.from).output,
  };
}

function refusedWireOf(
  refused: Refused | null,
  layout: GraphLayout<Wire>,
  orientation: Orientation
): RefusedWire | null {
  if (!refused) {
    return null;
  }
  const from = layout.places[refused.from].output;
  const target = layout.places[refused.to];
  const end = target.input ?? target.output;
  return { id: refused.id, path: wirePathOf(from, end, orientation), end };
}

function boxOf(layout: GraphLayout<Wire>, id: NodeId | null) {
  if (id === null) {
    return null;
  }
  return layout.places[id].box;
}

function inputOf(layout: GraphLayout<Wire>, id: NodeId | null) {
  if (id === null) {
    return null;
  }
  return layout.places[id].input;
}

/** A wire is never over the node it leaves. */
function otherThan(from: NodeId, found: NodeId | null) {
  if (found === from) {
    return null;
  }
  return found;
}

function clientPointOf(event: React.PointerEvent<HTMLDivElement>): Point {
  return { x: event.clientX, y: event.clientY };
}

/**
 * The canvas owns the wheel and the touch gestures while it holds the focus. Some browsers do not
 * give the focus to what is pressed, so the frame takes it first.
 */
function engage(frame: HTMLDivElement) {
  if (!frame.contains(document.activeElement)) {
    frame.focus({ preventScroll: true });
  }
}

export type CanvasProps = {
  /** False until the editor knows how wide it is, and so which way the pipeline reads. */
  isLaidOut: boolean;
  label: string;
  /** What Fit brings into view, for its accessible name. */
  subject: string;
  hintId: string;
  layout: GraphLayout<Wire>;
  orientation: Orientation;
  wires: Wire[];
  params: Params;
  runs: Record<NodeId, NodeRun>;
  /** The node a run is on, which the view follows. */
  runningId: NodeId | null;
  wiring: Wiring | null;
  refused: Refused | null;
  isDemonstrating: boolean;
  pressed: string | null;
  onAction: (action: GraphAction) => void;
  onRun: () => void;
};

export function Canvas({
  isLaidOut,
  label,
  subject,
  hintId,
  layout,
  orientation,
  wires,
  params,
  runs,
  runningId,
  wiring,
  refused,
  isDemonstrating,
  pressed,
  onAction,
  onRun,
}: CanvasProps) {
  const { frameRef, planeRef, view, isMeasured } = usePanZoom();
  const isReady = isMeasured && isLaidOut;
  const [isPointerWiring, setIsPointerWiring] = useState(false);
  const gesture = useRef<Gesture | null>(null);
  const liveRef = useRef<SVGPathElement>(null);
  const isLocked = runningId !== null;
  const held = heldWiringOf(isDemonstrating || isPointerWiring, wiring);
  const demoWiring = heldWiringOf(!isPointerWiring, held);
  const demoWire = demoWireOf(demoWiring, layout, orientation);
  const refusedWire = refusedWireOf(refused, layout, orientation);
  const followedId = runningId ?? demoWiring?.to ?? refused?.to ?? null;
  const pinnedBox = boxOf(layout, followedId);

  useLayoutEffect(() => {
    view.setScene(layout.bounds, 0);
  }, [view, layout.bounds]);

  useLayoutEffect(() => {
    view.pin(pinnedBox);
  }, [view, pinnedBox]);

  useLayoutEffect(() => {
    if (isReady) {
      view.settle();
    }
  }, [view, isReady, orientation]);

  /** The wire ends on the pointer, or on the port of the node it is over. */
  function drawLive(active: Wired, client: Point) {
    const point = view.toPlane(client);
    const from = layout.places[active.from].output;
    const found = nodeAt(layout.places, point, AIM_REACH);
    const aim = otherThan(active.from, found);
    const end = inputOf(layout, aim) ?? point;
    liveRef.current?.setAttribute('d', wirePathOf(from, end, orientation));
    if (aim !== active.aim) {
      active.aim = aim;
      onAction({ type: 'wireAimed', to: aim });
    }
  }

  function clearLive() {
    liveRef.current?.removeAttribute('d');
  }

  function startWire(event: React.PointerEvent<HTMLDivElement>, from: NodeId) {
    event.currentTarget.setPointerCapture(event.pointerId);
    const active: Wired = {
      kind: 'wire',
      pointerId: event.pointerId,
      from,
      aim: null,
    };
    gesture.current = active;
    const live = liveRef.current;
    if (live) {
      live.style.stroke = typeColorOf(nodeOf(from).output);
    }
    setIsPointerWiring(true);
    onAction({ type: 'wireStarted', from });
    drawLive(active, clientPointOf(event));
  }

  function startPan(event: React.PointerEvent<HTMLDivElement>) {
    event.currentTarget.setPointerCapture(event.pointerId);
    gesture.current = { kind: 'pan' };
    view.grab(event.pointerId, clientPointOf(event));
  }

  /** A press in the menu of a port reaches this handler through React, yet it is not on the canvas. */
  function startGesture(event: React.PointerEvent<HTMLDivElement>) {
    const target = event.target;
    const frame = event.currentTarget;
    const isMainButton = event.button === 0;
    const isOnCanvas = target instanceof Element && frame.contains(target);
    if (!isMainButton || !isOnCanvas) {
      return;
    }
    if (target.closest('[data-canvas-control]')) {
      return;
    }
    engage(frame);
    const active = gesture.current;
    if (active) {
      if (active.kind === 'pan') {
        startPan(event);
      }
      return;
    }
    const port = target.closest<HTMLElement>('[data-port]');
    const from = nodeIdOf(port?.dataset.port);
    if (from !== null && !isLocked) {
      startWire(event, from);
      return;
    }
    startPan(event);
  }

  function moveGesture(event: React.PointerEvent<HTMLDivElement>) {
    const active = gesture.current;
    if (!active) {
      return;
    }
    if (active.kind === 'pan') {
      view.drag(event.pointerId, clientPointOf(event));
      return;
    }
    if (event.pointerId === active.pointerId) {
      drawLive(active, clientPointOf(event));
    }
  }

  function endWire(action: GraphAction) {
    clearLive();
    setIsPointerWiring(false);
    onAction(action);
  }

  function finishGesture(
    event: React.PointerEvent<HTMLDivElement>,
    wireAction: GraphAction
  ) {
    const active = gesture.current;
    if (!active) {
      return;
    }
    if (active.kind === 'pan') {
      view.release(event.pointerId);
      if (!view.isHeld()) {
        gesture.current = null;
      }
      return;
    }
    if (event.pointerId !== active.pointerId) {
      return;
    }
    gesture.current = null;
    endWire(wireAction);
  }

  function endGesture(event: React.PointerEvent<HTMLDivElement>) {
    finishGesture(event, { type: 'wireDropped' });
  }

  function cancelGesture(event: React.PointerEvent<HTMLDivElement>) {
    finishGesture(event, { type: 'wireCancelled' });
  }

  function cancelOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    const active = gesture.current;
    const isWiring = active?.kind === 'wire';
    if (event.key !== 'Escape' || !isWiring) {
      return;
    }
    const frame = event.currentTarget;
    if (frame.hasPointerCapture(active.pointerId)) {
      frame.releasePointerCapture(active.pointerId);
    }
    gesture.current = null;
    endWire({ type: 'wireCancelled' });
  }

  /** A node that takes the focus from the keyboard is brought into view. A pressed one is already under the pointer. */
  function revealNode(id: NodeId) {
    const isPointerDown = gesture.current !== null;
    if (!isPointerDown) {
      view.reveal(layout.places[id].box);
    }
  }

  return (
    <>
      <div
        ref={frameRef}
        role='group'
        aria-label={label}
        aria-describedby={hintId}
        tabIndex={-1}
        onPointerDown={startGesture}
        onPointerMove={moveGesture}
        onPointerUp={endGesture}
        onPointerCancel={cancelGesture}
        onLostPointerCapture={cancelGesture}
        onKeyDown={cancelOnEscape}
        className={FRAME}
      >
        <div
          ref={planeRef}
          className={cn(
            'absolute top-0 left-0 origin-top-left',
            !isReady && 'invisible'
          )}
        >
          <WireLayer layout={layout} />
          {NODES.map((node) => (
            <NodeCard
              key={node.id}
              node={node}
              place={layout.places[node.id]}
              run={runs[node.id]}
              params={params}
              wires={wires}
              sourceId={sourceOf(wires, node.id)}
              signature={signatureOf(wires, params, node.id)}
              aim={aimOf(held, wires, node.id)}
              isOutputHeld={
                held?.from === node.id || pressed === `out-${node.id}`
              }
              isLocked={isLocked}
              isRetryPressed={pressed === 'retry'}
              onAction={onAction}
              onRun={onRun}
              onReveal={revealNode}
            />
          ))}
          <HeldLayer demo={demoWire} refused={refusedWire} liveRef={liveRef} />
          {refused && refusedWire && (
            <RefusalNote
              key={refused.id}
              at={refusedWire.end}
              reason={refused.reason}
            />
          )}
        </div>
      </div>
      <ZoomControl view={view} subject={subject} />
    </>
  );
}

type RefusalNoteProps = {
  at: Point;
  reason: string;
};

/**
 * Why the wire was refused, said where it was let go. It is drawn inside the canvas, hanging from
 * a point without width, so it never leaves the block nor widens the page.
 */
function RefusalNote({ at, reason }: RefusalNoteProps) {
  const noteStyle = { transform: `translate(${at.x}px, ${at.y - 14}px)` };

  return (
    <div style={noteStyle} className='absolute top-0 left-0 z-10 w-0'>
      <p className='surface-raised text-destructive-ink w-max max-w-56 -translate-x-1/2 -translate-y-full rounded-lg px-2 py-1 text-xs leading-snug font-medium text-balance transition-opacity duration-150 starting:opacity-0'>
        {reason}
      </p>
    </div>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import {
  ArrowRightIcon,
  CircleCheckIcon,
  CircleXIcon,
  CpuIcon,
  FileTextIcon,
  MessageSquareTextIcon,
  MinusIcon,
  PlusIcon,
  ScissorsIcon,
  SearchIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuShortcut,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Input } from '@/registry/ndeko/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/registry/ndeko/ui/select';
import { Slider } from '@/registry/ndeko/ui/slider';

import {
  CHUNK_SIZE,
  EMBED_MODELS,
  NODES,
  TOP_K,
  TYPE_WORD,
  type NodeId,
  type NodeSpec,
  type Params,
  type PortType,
} from './data';
import type { NodePlace, Point } from './layout';
import { refusalOf } from './pipeline';
import type { GraphAction, NodeRun, RunStatus, Wire } from './session';
import { typeColorOf } from './wires';

/** What a held wire makes of a node: where it leaves, a node that can take it, the one it is over, or one that cannot. */
export type Aim = 'idle' | 'source' | 'open' | 'aimed' | 'refusing' | 'closed';

const NODE_ICON: Record<NodeId, Icon> = {
  load: FileTextIcon,
  split: ScissorsIcon,
  embed: CpuIcon,
  search: SearchIcon,
  answer: MessageSquareTextIcon,
};

const STATUS_WORD: Record<RunStatus, string> = {
  idle: 'Not run',
  running: 'Running',
  done: 'Done',
  cached: 'Served from cache',
  failed: 'Failed',
  skipped: 'Skipped',
};

const CARD =
  'bg-card hairline-ring ring-border flex size-full flex-col rounded-xl p-2.5 shadow-[0_1px_2px_rgb(0_0_0/0.04)] transition-[box-shadow,opacity] duration-150';

const STATUS_RING: Partial<Record<RunStatus, string>> = {
  running: 'ring-primary/60 ring-2',
  failed: 'ring-destructive/50 ring-2',
};

const AIM_RING: Record<Aim, string> = {
  idle: '',
  source: '',
  open: 'ring-primary/45 ring-2',
  aimed: 'ring-primary ring-2',
  refusing: 'ring-destructive/70 ring-2',
  closed: 'opacity-50',
};

const PORT =
  'group/port absolute top-0 left-0 flex size-6 items-center justify-center rounded-full outline-none';

const DOT =
  'ring-card size-3 rounded-full ring-2 transition-[scale] duration-150 ease-(--ease-out-strong) group-hover/port:scale-125 group-focus-visible/port:scale-125';

const NOTHING = 'nothing';

/** A port sits on the edge of its node, in a square large enough for a finger. */
function portStyleOf(port: Point, place: NodePlace) {
  const x = port.x - place.box.x - 12;
  const y = port.y - place.box.y - 12;
  return { transform: `translate(${x}px, ${y}px)` };
}

function heldDotOf(isHeld: boolean) {
  if (isHeld) {
    return 'scale-150';
  }
  return undefined;
}

function staleToneOf(isStale: boolean) {
  if (isStale) {
    return 'opacity-50';
  }
  return undefined;
}

function TypeMark({ type }: { type: PortType }) {
  return (
    <span className='flex items-center gap-1'>
      <span
        aria-hidden='true'
        style={{ backgroundColor: typeColorOf(type) }}
        className='size-1.5 rounded-full'
      />
      {TYPE_WORD[type]}
    </span>
  );
}

/** The ring closes over the time the node runs. It is drawn once per run and never loops. */
function ProgressRing({ ms }: { ms: number }) {
  const ringStyle = { transitionDuration: `${ms}ms` };

  return (
    <svg viewBox='0 0 16 16' aria-hidden='true' className='size-4 -rotate-90'>
      <circle
        cx='8'
        cy='8'
        r='6'
        className='stroke-foreground/15 fill-none stroke-2'
      />
      <circle
        cx='8'
        cy='8'
        r='6'
        pathLength='1'
        strokeDasharray='1'
        style={ringStyle}
        className='stroke-primary fill-none stroke-2 transition-[stroke-dashoffset] ease-linear [stroke-dashoffset:0] [stroke-linecap:round] starting:[stroke-dashoffset:1]'
      />
    </svg>
  );
}

function StatusMark({ status, ms }: { status: RunStatus; ms: number }) {
  return (
    <span className='flex h-5 shrink-0 items-center'>
      <Swap swapKey={status}>
        {status === 'running' && <ProgressRing ms={ms} />}
        {status === 'done' && (
          <CircleCheckIcon className='text-success-foreground size-4' />
        )}
        {status === 'cached' && <Badge variant='secondary'>Cached</Badge>}
        {status === 'failed' && (
          <CircleXIcon className='text-destructive-ink size-4' />
        )}
        {status === 'skipped' && <Badge variant='outline'>Skipped</Badge>}
      </Swap>
      <span className='sr-only'>{STATUS_WORD[status]}</span>
    </span>
  );
}

type WidgetProps = {
  node: NodeSpec;
  params: Params;
  isLocked: boolean;
  onAction: (action: GraphAction) => void;
};

function SizeWidget({ node, params, isLocked, onAction }: WidgetProps) {
  function change(next: number | readonly number[]) {
    if (typeof next === 'number') {
      onAction({ type: 'paramsChanged', params: { chunkSize: next } });
    }
  }

  return (
    <>
      <span className='text-muted-foreground shrink-0 text-xs'>Size</span>
      <Slider
        value={params.chunkSize}
        min={CHUNK_SIZE.min}
        max={CHUNK_SIZE.max}
        step={CHUNK_SIZE.step}
        disabled={isLocked}
        thumbLabels={[`Chunk size of ${node.title}, in tokens`]}
        onValueChange={change}
      />
      <span className='w-9 shrink-0 text-end text-xs tabular-nums'>
        {params.chunkSize}
      </span>
    </>
  );
}

function ModelWidget({ node, params, isLocked, onAction }: WidgetProps) {
  function change(next: unknown) {
    const model = EMBED_MODELS.find((candidate) => candidate.value === next);
    if (model) {
      onAction({ type: 'paramsChanged', params: { model: model.value } });
    }
  }

  return (
    <Select
      items={EMBED_MODELS}
      value={params.model}
      disabled={isLocked}
      onValueChange={change}
    >
      <SelectTrigger size='sm' aria-label={`Model of ${node.title}`}>
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {EMBED_MODELS.map((model) => (
          <SelectItem key={model.value} value={model.value}>
            {model.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

function TopWidget({ params, isLocked, onAction }: WidgetProps) {
  const isLowest = params.topK <= TOP_K.min;
  const isHighest = params.topK >= TOP_K.max;

  function step(by: number) {
    onAction({ type: 'paramsChanged', params: { topK: params.topK + by } });
  }

  return (
    <>
      <span className='text-muted-foreground flex-1 text-xs'>Passages</span>
      <Button
        type='button'
        variant='outline'
        size='icon-sm'
        aria-label='One passage fewer'
        disabled={isLocked || isLowest}
        focusableWhenDisabled
        onClick={() => step(-1)}
        className='size-6'
      >
        <MinusIcon className='size-3.5' />
      </Button>
      <output
        aria-label='Passages to keep'
        className='w-5 text-center text-xs font-medium'
      >
        <MotionNumber value={params.topK} />
      </output>
      <Button
        type='button'
        variant='outline'
        size='icon-sm'
        aria-label='One passage more'
        disabled={isLocked || isHighest}
        focusableWhenDisabled
        onClick={() => step(1)}
        className='size-6'
      >
        <PlusIcon className='size-3.5' />
      </Button>
    </>
  );
}

function PromptWidget({ node, params, isLocked, onAction }: WidgetProps) {
  return (
    <Input
      size='sm'
      value={params.prompt}
      disabled={isLocked}
      autoComplete='off'
      aria-label={`Question for ${node.title}`}
      placeholder='Ask the help center'
      onChange={(event) =>
        onAction({
          type: 'paramsChanged',
          params: { prompt: event.target.value },
        })
      }
    />
  );
}

/** The setting of each node, edited where it applies. Loading has nothing to set. */
function Widget(props: WidgetProps) {
  const id = props.node.id;
  if (id === 'split') {
    return <SizeWidget {...props} />;
  }
  if (id === 'embed') {
    return <ModelWidget {...props} />;
  }
  if (id === 'search') {
    return <TopWidget {...props} />;
  }
  if (id === 'answer') {
    return <PromptWidget {...props} />;
  }
  return (
    <span className='text-muted-foreground truncate text-xs'>
      Source · Help center
    </span>
  );
}

type PreviewProps = {
  node: NodeSpec;
  run: NodeRun;
  isStale: boolean;
  isRetryPressed: boolean;
  onRun: () => void;
};

/** What the node last produced. A result older than its settings stays, dimmed, until the next run. */
function Preview({ node, run, isStale, isRetryPressed, onRun }: PreviewProps) {
  const { status, result } = run;

  if (status === 'running') {
    return <p className='text-muted-foreground text-xs'>{node.workingLine}</p>;
  }
  if (status === 'failed') {
    return (
      <div className='flex items-start gap-2'>
        <p className='text-destructive-ink line-clamp-2 min-w-0 flex-1 text-xs'>
          {run.message}
        </p>
        <Button
          type='button'
          size='sm'
          variant='outline'
          data-canvas-control
          onClick={onRun}
          className={cn('h-6 shrink-0 px-2', pressedQuietOf(isRetryPressed))}
        >
          Retry
        </Button>
      </div>
    );
  }
  if (status === 'skipped') {
    return <p className='text-muted-foreground text-xs'>{run.message}</p>;
  }
  if (!result) {
    return <p className='text-muted-foreground text-xs'>Not run yet</p>;
  }

  return (
    <div
      className={cn(
        'flex flex-col transition-opacity duration-200',
        staleToneOf(isStale)
      )}
    >
      <p className='text-[13px] leading-5 font-medium tabular-nums'>
        {result.headline}
        {isStale && <span className='sr-only'>, out of date</span>}
      </p>
      <p className='text-muted-foreground line-clamp-2 text-xs leading-4'>
        {result.lines.join(', ')}
      </p>
    </div>
  );
}

type InputPortProps = {
  node: NodeSpec;
  type: PortType;
  port: Point;
  place: NodePlace;
  wires: Wire[];
  sourceId: NodeId | null;
  isLocked: boolean;
  onAction: (action: GraphAction) => void;
};

function sourceWordOf(sourceId: NodeId | null) {
  const source = NODES.find((candidate) => candidate.id === sourceId);
  if (!source) {
    return 'Not connected';
  }
  return `Fed by ${source.title}`;
}

/** Connecting without dragging: the port opens the nodes that can feed it. The others say what they give. */
function InputPort({
  node,
  type,
  port,
  place,
  wires,
  sourceId,
  isLocked,
  onAction,
}: InputPortProps) {
  const others = NODES.filter((candidate) => candidate.id !== node.id);

  function choose(next: unknown) {
    const source = others.find((candidate) => candidate.id === next);
    if (source) {
      onAction({ type: 'connected', from: source.id, to: node.id });
      return;
    }
    onAction({ type: 'disconnected', to: node.id });
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        data-canvas-control
        disabled={isLocked}
        aria-label={`Input of ${node.title}: ${TYPE_WORD[type]}. ${sourceWordOf(sourceId)}`}
        style={portStyleOf(port, place)}
        className={cn(
          PORT,
          'focus-visible:ring-ring cursor-pointer focus-visible:ring-2'
        )}
      >
        <span style={{ backgroundColor: typeColorOf(type) }} className={DOT} />
      </DropdownMenuTrigger>
      <DropdownMenuContent className='min-w-60'>
        <DropdownMenuLabel>Feed {node.title} from</DropdownMenuLabel>
        <DropdownMenuRadioGroup
          value={sourceId ?? NOTHING}
          onValueChange={choose}
        >
          {others.map((candidate) => (
            <DropdownMenuRadioItem
              key={candidate.id}
              value={candidate.id}
              disabled={refusalOf(wires, candidate.id, node.id) !== null}
            >
              {candidate.title}
              <DropdownMenuShortcut>
                {TYPE_WORD[candidate.output]}
              </DropdownMenuShortcut>
            </DropdownMenuRadioItem>
          ))}
          <DropdownMenuRadioItem value={NOTHING}>Nothing</DropdownMenuRadioItem>
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function spokenOf(node: NodeSpec, run: NodeRun, sourceId: NodeId | null) {
  const status = STATUS_WORD[run.status];
  if (node.input === null) {
    return `${node.title}. ${status}`;
  }
  return `${node.title}. ${sourceWordOf(sourceId)}. ${status}`;
}

export type NodeCardProps = {
  node: NodeSpec;
  place: NodePlace;
  run: NodeRun;
  params: Params;
  wires: Wire[];
  sourceId: NodeId | null;
  /** What the node would compute now. A result with another signature is out of date. */
  signature: string;
  aim: Aim;
  /** A wire is held out of its output, by a pointer or by the demonstration. */
  isOutputHeld: boolean;
  /** A run is going: settings and wires wait until it ends. */
  isLocked: boolean;
  isRetryPressed: boolean;
  onAction: (action: GraphAction) => void;
  onRun: () => void;
  onReveal: (id: NodeId) => void;
};

export function NodeCard({
  node,
  place,
  run,
  params,
  wires,
  sourceId,
  signature,
  aim,
  isOutputHeld,
  isLocked,
  isRetryPressed,
  onAction,
  onRun,
  onReveal,
}: NodeCardProps) {
  const Glyph = NODE_ICON[node.id];
  const { box } = place;
  const cardStyle = { transform: `translate(${box.x}px, ${box.y}px)` };

  return (
    <div
      data-node={node.id}
      role='group'
      aria-label={spokenOf(node, run, sourceId)}
      style={cardStyle}
      onFocus={() => onReveal(node.id)}
      className='absolute top-0 left-0 h-[168px] w-[216px]'
    >
      <div className={cn(CARD, STATUS_RING[run.status], AIM_RING[aim])}>
        <p className='text-muted-foreground flex h-5 items-center gap-1.5 text-[11px]'>
          {node.input && <TypeMark type={node.input} />}
          {node.input && <ArrowRightIcon className='size-3' />}
          <TypeMark type={node.output} />
        </p>
        <div className='mt-1 flex h-7 items-center gap-2'>
          <span
            aria-hidden='true'
            className='keycap-3d text-muted-foreground inline-flex size-6 shrink-0 items-center justify-center rounded-md'
          >
            <Glyph className='size-3.5' />
          </span>
          <h3 className='min-w-0 flex-1 truncate text-[13px] font-medium'>
            {node.title}
          </h3>
          <StatusMark status={run.status} ms={node.runMs} />
        </div>
        <div data-canvas-control className='mt-1.5 flex h-8 items-center gap-2'>
          <Widget
            node={node}
            params={params}
            isLocked={isLocked}
            onAction={onAction}
          />
        </div>
        <div className='mt-2 h-[46px] overflow-hidden'>
          <Preview
            node={node}
            run={run}
            isStale={run.signature !== signature}
            isRetryPressed={isRetryPressed}
            onRun={onRun}
          />
        </div>
      </div>
      {node.input && place.input && (
        <InputPort
          node={node}
          type={node.input}
          port={place.input}
          place={place}
          wires={wires}
          sourceId={sourceId}
          isLocked={isLocked}
          onAction={onAction}
        />
      )}
      <span
        data-port={node.id}
        aria-hidden='true'
        style={portStyleOf(place.output, place)}
        className={cn(PORT, 'cursor-crosshair')}
      >
        <span
          style={{ backgroundColor: typeColorOf(node.output) }}
          className={cn(DOT, heldDotOf(isOutputHeld))}
        />
      </span>
    </div>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';

import { TYPE_SERIES, type PortType } from './data';
import type { GraphLayout, PlacedWire, Point } from './layout';
import type { Wire } from './session';

const LAYER =
  'pointer-events-none absolute top-0 left-0 size-px overflow-visible';

const WIRE = 'fill-none stroke-2 [stroke-linecap:round]';

/** A wire that has just been made shows at full strength, then settles among the others. */
const SETTLING =
  'opacity-70 transition-opacity duration-500 starting:opacity-100';

const DRAW = { duration: 0.5, ease: EASE_OUT_STRONG };

const REACH = { duration: 0.45, ease: EASE_OUT_STRONG };

const SHAKE = { duration: 0.34, ease: EASE_OUT_STRONG };

/** An error nudges once: four pixels each way, then back. */
const SHAKEN = { x: [0, -4, 4, -3, 3, 0] };

const STILL = { x: 0 };

const LEAVE = { opacity: 0, transition: { duration: 0.15 } };

export function typeColorOf(type: PortType) {
  return seriesColorOf(TYPE_SERIES[type]);
}

function drawStartOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return { pathLength: 1 };
  }
  return { pathLength: 0 };
}

function shakeOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return STILL;
  }
  return SHAKEN;
}

/** Only a wire made from a menu draws itself: one let go by a hand is already where it lands. */
function WirePath({ wire }: { wire: PlacedWire<Wire> }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const style = { stroke: typeColorOf(wire.type) };

  if (wire.link.arrival === 'drawn') {
    return (
      <motion.path
        d={wire.path}
        style={style}
        initial={drawStartOf(shouldReduceMotion)}
        animate={{ pathLength: 1 }}
        transition={DRAW}
        className={cn(WIRE, SETTLING)}
      />
    );
  }

  const hasLanded = wire.link.arrival === 'dropped';

  return (
    <path
      d={wire.path}
      style={style}
      className={cn(WIRE, 'opacity-70', hasLanded && SETTLING)}
    />
  );
}

export function WireLayer({ layout }: { layout: GraphLayout<Wire> }) {
  return (
    <svg aria-hidden='true' className={LAYER}>
      {layout.wires.map((wire) => (
        <WirePath key={wire.id} wire={wire} />
      ))}
    </svg>
  );
}

export type HeldWire = {
  path: string;
  type: PortType;
};

export type RefusedWire = {
  id: number;
  path: string;
  end: Point;
};

type HeldLayerProps = {
  /** The wire the demonstration holds out, from its port to the node it aims at. */
  demo: HeldWire | null;
  /** A wire that was refused: it stays a moment, its end shakes once, then it leaves. */
  refused: RefusedWire | null;
  /** The wire a pointer holds. Its path is written to the element on every move, never rendered. */
  liveRef: React.Ref<SVGPathElement>;
};

export function HeldLayer({ demo, refused, liveRef }: HeldLayerProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <svg aria-hidden='true' className={LAYER}>
      {demo && (
        <motion.path
          key={demo.path}
          d={demo.path}
          style={{ stroke: typeColorOf(demo.type) }}
          initial={drawStartOf(shouldReduceMotion)}
          animate={{ pathLength: 1 }}
          transition={REACH}
          className={WIRE}
        />
      )}
      <AnimatePresence>
        {refused && (
          <motion.g key={refused.id} exit={LEAVE}>
            <path
              d={refused.path}
              className={cn(WIRE, 'stroke-destructive [stroke-dasharray:4_5]')}
            />
            <motion.circle
              cx={refused.end.x}
              cy={refused.end.y}
              r={5}
              animate={shakeOf(shouldReduceMotion)}
              transition={SHAKE}
              className='fill-destructive'
            />
          </motion.g>
        )}
      </AnimatePresence>
      <path ref={liveRef} className={WIRE} />
    </svg>
  );
}

'use client';

import { MaximizeIcon, MinusIcon, PlusIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import {
  MAX_ZOOM,
  MIN_ZOOM,
  useZoomPercent,
  type CanvasView,
} from './use-pan-zoom';

const ZOOM_STEP = 1.25;

const MIN_PERCENT = Math.round(MIN_ZOOM * 100);

const MAX_PERCENT = Math.round(MAX_ZOOM * 100);

type ZoomControlProps = {
  view: CanvasView;
  /** What Fit brings into view, for its accessible name. */
  subject: string;
};

/** It sits on the canvas and is the only part that renders again while the zoom changes. */
export function ZoomControl({ view, subject }: ZoomControlProps) {
  const percent = useZoomPercent(view);
  const isSmallest = percent <= MIN_PERCENT;
  const isLargest = percent >= MAX_PERCENT;

  return (
    <div
      role='group'
      aria-label='Zoom'
      className='bg-card hairline-ring ring-border absolute bottom-3 left-3 flex items-center gap-0.5 rounded-full p-0.5 shadow-[0_1px_2px_rgb(0_0_0/0.05)]'
    >
      <Button
        type='button'
        variant='ghost'
        size='icon-sm'
        aria-label='Zoom out'
        disabled={isSmallest}
        focusableWhenDisabled
        onClick={() => view.zoomStep(1 / ZOOM_STEP)}
        className='rounded-full'
      >
        <MinusIcon />
      </Button>
      <Button
        type='button'
        variant='ghost'
        size='sm'
        aria-label={`Zoom ${percent}%. Reset to 100%`}
        onClick={() => view.zoomTo(1)}
        className='w-12 rounded-full px-0 tabular-nums'
      >
        {percent}%
      </Button>
      <Button
        type='button'
        variant='ghost'
        size='icon-sm'
        aria-label='Zoom in'
        disabled={isLargest}
        focusableWhenDisabled
        onClick={() => view.zoomStep(ZOOM_STEP)}
        className='rounded-full'
      >
        <PlusIcon />
      </Button>
      <Button
        type='button'
        variant='ghost'
        size='icon-sm'
        aria-label={`Fit ${subject} in view`}
        onClick={() => view.fit()}
        className='rounded-full'
      >
        <MaximizeIcon />
      </Button>
    </div>
  );
}

'use client';

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from 'react';

type Point = {
  x: number;
  y: number;
};

type Box = Point & {
  width: number;
  height: number;
};

type Viewport = Point & {
  zoom: number;
};

type Span = {
  centre: Point;
  distance: number;
};

export const MIN_ZOOM = 0.4;

export const MAX_ZOOM = 1.6;

/** Fit never enlarges past full size: a small flow stays readable instead of filling the frame. */
const FIT_MAX_ZOOM = 1;

/** Nor does it shrink a flow until its text cannot be read: what does not fit is reached by panning. */
const FIT_MIN_ZOOM = 0.75;

const FIT_MARGIN = 20;

const REVEAL_MARGIN = 16;

const EASED = 'transform 220ms cubic-bezier(0.23, 1, 0.32, 1)';

/** A wheel that reports lines, as some mice do, moves this many pixels a line. */
const LINE_PIXELS = 16;

const WHEEL_DOM_DELTA_LINE = 1;

const WHEEL_ZOOM_RATE = 0.01;

/** One wheel event never zooms by more than about a quarter. */
const WHEEL_ZOOM_LIMIT = 24;

const NO_BOX: Box = { x: 0, y: 0, width: 1, height: 1 };

function clamp(value: number, min: number, max: number) {
  const atLeast = Math.max(value, min);
  return Math.min(atLeast, max);
}

function transitionOf(isEased: boolean) {
  if (isEased) {
    return EASED;
  }
  return 'none';
}

/** How far a span has to move to sit between two edges. Its start wins when it is too long to fit. */
function shiftOf(start: number, end: number, min: number, max: number) {
  if (start < min) {
    return min - start;
  }
  if (end > max) {
    const back = max - end;
    const untilStart = min - start;
    return Math.max(back, untilStart);
  }
  return 0;
}

/**
 * Where the content starts along one axis of the frame: centred when it fits, at the margin when it
 * does not, so the start of the flow is what shows.
 */
function startOf(
  frameSize: number,
  contentStart: number,
  contentSize: number,
  zoom: number
) {
  const scaled = contentSize * zoom;
  const room = frameSize - FIT_MARGIN * 2;
  if (scaled <= room) {
    return (frameSize - scaled) / 2 - contentStart * zoom;
  }
  return FIT_MARGIN - contentStart * zoom;
}

function spanOf(pointers: Map<number, Point>): Span | null {
  const [first, second] = Array.from(pointers.values());
  if (!first || !second) {
    return null;
  }
  const centre = { x: (first.x + second.x) / 2, y: (first.y + second.y) / 2 };
  const distance = Math.hypot(second.x - first.x, second.y - first.y);
  return { centre, distance };
}

function wheelUnitOf(event: WheelEvent) {
  if (event.deltaMode === WHEEL_DOM_DELTA_LINE) {
    return LINE_PIXELS;
  }
  return 1;
}

/** Ctrl or Cmd with the wheel, which is also how a trackpad reports a pinch. */
function isZoomWheel(event: WheelEvent) {
  return event.ctrlKey || event.metaKey;
}

/**
 * Pan and zoom of a canvas as one transform on one plane element. The transform is written to the
 * element, never through React state: a drag or a pinch changes it on every frame.
 */
export function createCanvasView() {
  let frame: HTMLElement | null = null;
  let plane: HTMLElement | null = null;
  let viewport: Viewport = { x: 0, y: 0, zoom: 1 };
  let content = NO_BOX;
  let coveredShare = 0;
  let pinned: Box | null = null;
  /** True once a person has moved the view: it is no longer refitted when the frame changes size. */
  let isManual = false;
  let hasFitted = false;
  const listeners = new Set<() => void>();
  const pointers = new Map<number, Point>();

  function sizeOf() {
    if (!frame) {
      return null;
    }
    return { width: frame.clientWidth, height: frame.clientHeight };
  }

  function apply(next: Viewport, isEased: boolean) {
    const x = Math.round(next.x);
    const y = Math.round(next.y);
    viewport = { x, y, zoom: next.zoom };
    if (plane) {
      plane.style.transition = transitionOf(isEased);
      plane.style.transform = `translate(${x}px, ${y}px) scale(${next.zoom})`;
    }
    listeners.forEach((listener) => listener());
  }

  function localOf(client: Point): Point {
    const rect = frame?.getBoundingClientRect();
    if (!rect) {
      return client;
    }
    return { x: client.x - rect.left, y: client.y - rect.top };
  }

  function centreOf(): Point {
    const size = sizeOf();
    if (!size) {
      return { x: 0, y: 0 };
    }
    return { x: size.width / 2, y: size.height / 2 };
  }

  /** The point under `anchor` stays under it while the zoom changes. */
  function zoomedAround(factor: number, anchor: Point): Viewport {
    const zoom = clamp(viewport.zoom * factor, MIN_ZOOM, MAX_ZOOM);
    const ratio = zoom / viewport.zoom;
    const x = anchor.x - (anchor.x - viewport.x) * ratio;
    const y = anchor.y - (anchor.y - viewport.y) * ratio;
    return { x, y, zoom };
  }

  function fitted(): Viewport | null {
    const size = sizeOf();
    if (!size) {
      return null;
    }
    const roomX = size.width - FIT_MARGIN * 2;
    const roomY = size.height - FIT_MARGIN * 2;
    const scale = Math.min(roomX / content.width, roomY / content.height);
    const zoom = clamp(scale, FIT_MIN_ZOOM, FIT_MAX_ZOOM);
    const x = startOf(size.width, content.x, content.width, zoom);
    const y = startOf(size.height, content.y, content.height, zoom);
    return { x, y, zoom };
  }

  function revealed(box: Box): Viewport | null {
    const size = sizeOf();
    if (!size) {
      return null;
    }
    const left = box.x * viewport.zoom + viewport.x;
    const top = box.y * viewport.zoom + viewport.y;
    const right = left + box.width * viewport.zoom;
    const bottom = top + box.height * viewport.zoom;
    const visibleHeight = size.height * (1 - coveredShare);
    const maxX = size.width - REVEAL_MARGIN;
    const maxY = visibleHeight - REVEAL_MARGIN;
    const dx = shiftOf(left, right, REVEAL_MARGIN, maxX);
    const dy = shiftOf(top, bottom, REVEAL_MARGIN, maxY);
    if (dx === 0 && dy === 0) {
      return null;
    }
    return { ...viewport, x: viewport.x + dx, y: viewport.y + dy };
  }

  function refit(isEased: boolean) {
    const next = fitted();
    if (next) {
      hasFitted = true;
      apply(next, isEased);
    }
  }

  /**
   * Focus on a step outside the frame makes the browser scroll the frame to it. The scroll is taken
   * back and given to the transform, so the plane stays the only thing that moves.
   */
  function absorbScroll() {
    if (!frame) {
      return;
    }
    const left = frame.scrollLeft;
    const top = frame.scrollTop;
    if (left === 0 && top === 0) {
      return;
    }
    frame.scrollLeft = 0;
    frame.scrollTop = 0;
    apply({ ...viewport, x: viewport.x - left, y: viewport.y - top }, false);
  }

  function reveal(box: Box) {
    absorbScroll();
    if (!hasFitted) {
      return;
    }
    const next = revealed(box);
    if (next) {
      apply(next, true);
    }
  }

  function panBy(dx: number, dy: number) {
    isManual = true;
    apply({ ...viewport, x: viewport.x + dx, y: viewport.y + dy }, false);
  }

  function pinch(before: Span, after: Span) {
    if (before.distance === 0) {
      return;
    }
    const factor = after.distance / before.distance;
    const zoomed = zoomedAround(factor, localOf(before.centre));
    const x = zoomed.x + after.centre.x - before.centre.x;
    const y = zoomed.y + after.centre.y - before.centre.y;
    isManual = true;
    apply({ x, y, zoom: zoomed.zoom }, false);
  }

  return {
    /** The frame that clips the canvas and the plane that moves inside it. */
    attach(nextFrame: HTMLElement | null, nextPlane: HTMLElement | null) {
      frame = nextFrame;
      plane = nextPlane;
    },
    subscribe(listener: () => void) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    percent() {
      return Math.round(viewport.zoom * 100);
    },
    zoom() {
      return viewport.zoom;
    },
    origin(): Point {
      return { x: viewport.x, y: viewport.y };
    },
    /** A point of the screen as a point of the plane. */
    toPlane(client: Point): Point {
      const local = localOf(client);
      const x = (local.x - viewport.x) / viewport.zoom;
      const y = (local.y - viewport.y) / viewport.zoom;
      return { x, y };
    },
    panBy,
    zoomStep(factor: number) {
      isManual = true;
      apply(zoomedAround(factor, centreOf()), true);
    },
    zoomTo(zoom: number) {
      isManual = true;
      apply(zoomedAround(zoom / viewport.zoom, centreOf()), true);
    },
    /** Shows everything again and hands the view back to the canvas, which refits it on its own. */
    fit() {
      isManual = false;
      refit(true);
    },
    /** What Fit shows, and the share of the frame a sheet covers from the bottom, from 0 to 1. */
    setScene(bounds: Box, covered: number) {
      content = bounds;
      coveredShare = covered;
    },
    /** Called when the frame, the layout or the sheet changed: refits a view nobody moved. */
    settle() {
      const isFirst = !hasFitted;
      if (isFirst || !isManual) {
        refit(!isFirst);
      }
      if (!pinned) {
        return;
      }
      const next = revealed(pinned);
      if (next) {
        apply(next, !isFirst);
      }
    },
    reveal,
    /** The box to keep in view, now and whenever the frame changes size. */
    pin(box: Box | null) {
      pinned = box;
      if (box) {
        reveal(box);
      }
    },
    absorbScroll,
    grab(pointerId: number, at: Point) {
      pointers.set(pointerId, at);
    },
    /** One pointer pans. Two pointers pinch: the zoom follows their distance, the pan their middle. */
    drag(pointerId: number, now: Point) {
      const last = pointers.get(pointerId);
      if (!last) {
        return;
      }
      const before = spanOf(pointers);
      pointers.set(pointerId, now);
      const after = spanOf(pointers);
      if (before && after) {
        pinch(before, after);
        return;
      }
      panBy(now.x - last.x, now.y - last.y);
    },
    release(pointerId: number) {
      pointers.delete(pointerId);
    },
    isHeld() {
      return pointers.size > 0;
    },
    /** A plain wheel pans. A zoom wheel zooms around the pointer. */
    takeWheel(event: WheelEvent) {
      const unit = wheelUnitOf(event);
      if (!isZoomWheel(event)) {
        panBy(-event.deltaX * unit, -event.deltaY * unit);
        return;
      }
      const raw = event.deltaY * unit;
      const delta = clamp(raw, -WHEEL_ZOOM_LIMIT, WHEEL_ZOOM_LIMIT);
      const factor = Math.exp(-delta * WHEEL_ZOOM_RATE);
      const anchor = localOf({ x: event.clientX, y: event.clientY });
      isManual = true;
      apply(zoomedAround(factor, anchor), false);
    },
  };
}

export type CanvasView = ReturnType<typeof createCanvasView>;

/**
 * The frame and the plane of a canvas, with its view. Call it in the component that renders them,
 * before any effect that uses the view. A plain wheel pans only while the focus is inside the
 * parent of the frame, so a page scrolled past the canvas keeps scrolling. A pinch always zooms the
 * canvas under it, never the page.
 */
export function usePanZoom() {
  const frameRef = useRef<HTMLDivElement>(null);
  const planeRef = useRef<HTMLDivElement>(null);
  const [view] = useState(createCanvasView);
  const [isMeasured, setIsMeasured] = useState(false);

  useLayoutEffect(() => {
    view.attach(frameRef.current, planeRef.current);
    return () => view.attach(null, null);
  }, [view]);

  useEffect(() => {
    const frame = frameRef.current;
    if (!frame) {
      return;
    }
    const scope = frame.parentElement ?? frame;
    let hasMeasured = false;

    /** The first fit is left to the canvas, which knows by then what it shows. */
    function measure() {
      setIsMeasured(true);
      if (hasMeasured) {
        view.settle();
      }
      hasMeasured = true;
    }

    function takeWheel(event: WheelEvent) {
      const isEngaged = scope.matches(':focus-within');
      const isZoom = isZoomWheel(event);
      if (!isEngaged && !isZoom) {
        return;
      }
      event.preventDefault();
      view.takeWheel(event);
    }

    const observer = new ResizeObserver(measure);
    observer.observe(frame);
    frame.addEventListener('wheel', takeWheel, { passive: false });
    frame.addEventListener('scroll', view.absorbScroll);
    return () => {
      observer.disconnect();
      frame.removeEventListener('wheel', takeWheel);
      frame.removeEventListener('scroll', view.absorbScroll);
    };
  }, [view]);

  return { frameRef, planeRef, view, isMeasured };
}

function fullSize() {
  return 100;
}

/** The zoom as a whole percentage. Only the text that shows it renders again when it changes. */
export function useZoomPercent(view: CanvasView) {
  return useSyncExternalStore(view.subscribe, view.percent, fullSize);
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

const PHONE_BELOW = 640;

/**
 * Whether the editor itself is as narrow as a phone, whatever the window: the pipeline then reads
 * from top to bottom. Null until the element has been measured, so nothing is laid out for the
 * wrong width first.
 */
export function useIsPhone(ref: RefObject<HTMLElement | null>) {
  const [isPhone, setIsPhone] = useState<boolean | null>(null);

  useEffect(() => {
    const element = ref.current;
    if (!element) {
      return;
    }
    const observer = new ResizeObserver(([entry]) => {
      setIsPhone(entry.contentRect.width < PHONE_BELOW);
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, [ref]);

  return isPhone;
}

import { nodeOf, NODES, type Link, type NodeId, type PortType } from './data';

/** A wide canvas reads from left to right. A phone reads from top to bottom. */
export type Orientation = 'across' | 'down';

export type Point = {
  x: number;
  y: number;
};

export type Box = Point & {
  width: number;
  height: number;
};

export const NODE_WIDTH = 216;

export const NODE_HEIGHT = 168;

/** The room between two nodes along the pipeline, where their wire runs. */
const GAP = 40;

/** How far every other node steps aside, so a wire curves instead of running straight. */
const ASIDE = 48;

/** The ports of a wide canvas sit on the first line of the node, beside its types. */
const PORT_INSET = 18;

/** How far a wire runs straight out of a port before it turns. */
const MIN_REACH = 28;

export type NodePlace = {
  box: Box;
  /** Where its wire arrives. The first node takes no input. */
  input: Point | null;
  output: Point;
};

export type PlacedWire<Wire extends Link> = {
  id: string;
  link: Wire;
  type: PortType;
  path: string;
};

export type GraphLayout<Wire extends Link> = {
  places: Record<NodeId, NodePlace>;
  wires: PlacedWire<Wire>[];
  bounds: Box;
};

function asideOf(isAside: boolean) {
  if (isAside) {
    return ASIDE;
  }
  return 0;
}

function boxOf(
  column: number,
  isAside: boolean,
  orientation: Orientation
): Box {
  const aside = asideOf(isAside);
  if (orientation === 'across') {
    const x = column * (NODE_WIDTH + GAP);
    return { x, y: aside, width: NODE_WIDTH, height: NODE_HEIGHT };
  }
  const y = column * (NODE_HEIGHT + GAP);
  return { x: aside, y, width: NODE_WIDTH, height: NODE_HEIGHT };
}

function placeOf(
  box: Box,
  hasInput: boolean,
  orientation: Orientation
): NodePlace {
  let input: Point = { x: box.x + box.width / 2, y: box.y };
  let output: Point = { x: box.x + box.width / 2, y: box.y + box.height };
  if (orientation === 'across') {
    input = { x: box.x, y: box.y + PORT_INSET };
    output = { x: box.x + box.width, y: box.y + PORT_INSET };
  }
  if (!hasInput) {
    return { box, input: null, output };
  }
  return { box, input, output };
}

export function wirePathOf(from: Point, to: Point, orientation: Orientation) {
  if (orientation === 'across') {
    const span = Math.abs(to.x - from.x);
    const reach = Math.max(MIN_REACH, span / 2);
    const leaveX = from.x + reach;
    const arriveX = to.x - reach;
    return `M ${from.x} ${from.y} C ${leaveX} ${from.y}, ${arriveX} ${to.y}, ${to.x} ${to.y}`;
  }
  const span = Math.abs(to.y - from.y);
  const reach = Math.max(MIN_REACH, span / 2);
  const leaveY = from.y + reach;
  const arriveY = to.y - reach;
  return `M ${from.x} ${from.y} C ${from.x} ${leaveY}, ${to.x} ${arriveY}, ${to.x} ${to.y}`;
}

function nodePlaceOf(id: NodeId, orientation: Orientation) {
  const node = nodeOf(id);
  const box = boxOf(node.column, node.isAside, orientation);
  return placeOf(box, node.input !== null, orientation);
}

function placesOf(orientation: Orientation): Record<NodeId, NodePlace> {
  return {
    load: nodePlaceOf('load', orientation),
    split: nodePlaceOf('split', orientation),
    embed: nodePlaceOf('embed', orientation),
    search: nodePlaceOf('search', orientation),
    answer: nodePlaceOf('answer', orientation),
  };
}

function boundsOf(places: NodePlace[]): Box {
  const rights = places.map((place) => place.box.x + place.box.width);
  const bottoms = places.map((place) => place.box.y + place.box.height);
  return {
    x: 0,
    y: 0,
    width: Math.max(...rights),
    height: Math.max(...bottoms),
  };
}

/** Everything the canvas draws, worked out from the nodes and their wires alone. */
export function layoutOf<Wire extends Link>(
  links: Wire[],
  orientation: Orientation
): GraphLayout<Wire> {
  const places = placesOf(orientation);
  const wires: PlacedWire<Wire>[] = [];
  for (const link of links) {
    const from = places[link.from].output;
    const to = places[link.to].input;
    if (to) {
      wires.push({
        id: `${link.from}:${link.to}`,
        link,
        type: nodeOf(link.from).output,
        path: wirePathOf(from, to, orientation),
      });
    }
  }
  return { places, wires, bounds: boundsOf(Object.values(places)) };
}

function contains(box: Box, point: Point, reach: number) {
  const isInsideX =
    point.x >= box.x - reach && point.x <= box.x + box.width + reach;
  const isInsideY =
    point.y >= box.y - reach && point.y <= box.y + box.height + reach;
  return isInsideX && isInsideY;
}

/** The node under a point of the canvas, with some reach around it so a wire lands easily. */
export function nodeAt(
  places: Record<NodeId, NodePlace>,
  point: Point,
  reach: number
) {
  const found = NODES.find((node) =>
    contains(places[node.id].box, point, reach)
  );
  return found?.id ?? null;
}

import {
  ANSWER_TEXT,
  ARTICLE_COUNT,
  EMBED_MODELS,
  nodeOf,
  NODES,
  PASSAGES,
  TOTAL_TOKENS,
  TYPE_WORD,
  type Link,
  type NodeId,
  type Params,
} from './data';

/** An input takes one wire, so a node has at most one source. An output may feed several nodes. */
export function sourceOf(links: Link[], id: NodeId) {
  const link = links.find((candidate) => candidate.to === id);
  return link?.from ?? null;
}

/** A node and every node its output reaches, in no particular order. */
export function downstreamOf(links: Link[], id: NodeId) {
  const reached: NodeId[] = [];
  const pending = [id];
  let current = pending.pop();
  while (current !== undefined) {
    if (!reached.includes(current)) {
      reached.push(current);
      const visited = current;
      const fed = links.filter((link) => link.from === visited);
      fed.forEach((link) => pending.push(link.to));
    }
    current = pending.pop();
  }
  return reached;
}

/**
 * Why the output of one node cannot feed another, said in one sentence, or null when it can. The
 * types of the two ports have to match, and a node never ends up fed by its own output.
 */
export function refusalOf(links: Link[], from: NodeId, to: NodeId) {
  const source = nodeOf(from);
  const target = nodeOf(to);
  if (from === to) {
    return `${source.title} cannot feed itself`;
  }
  if (target.input === null) {
    return `${target.title} takes no input`;
  }
  if (source.output !== target.input) {
    const wanted = TYPE_WORD[target.input];
    const given = TYPE_WORD[source.output];
    return `${target.title} takes ${wanted}. ${source.title} gives ${given}`;
  }
  if (downstreamOf(links, to).includes(from)) {
    return `That would feed ${source.title} its own output`;
  }
  return null;
}

export function missingInputOf(links: Link[], id: NodeId) {
  const node = nodeOf(id);
  const isFed = sourceOf(links, id) !== null;
  if (node.input === null || isFed) {
    return null;
  }
  return `${TYPE_WORD[node.input]} is not connected`;
}

/** Every node after the one that feeds it: the order a run follows. */
export function orderOf(links: Link[]) {
  const placed: NodeId[] = [];
  let waiting = NODES.map((node) => node.id);
  while (waiting.length > 0) {
    const ready = waiting.filter((id) => {
      const source = sourceOf(links, id);
      return source === null || placed.includes(source);
    });
    if (ready.length === 0) {
      return [...placed, ...waiting];
    }
    placed.push(...ready);
    waiting = waiting.filter((id) => !ready.includes(id));
  }
  return placed;
}

function settingOf(id: NodeId, params: Params) {
  if (id === 'split') {
    return String(params.chunkSize);
  }
  if (id === 'embed') {
    return params.model;
  }
  if (id === 'search') {
    return String(params.topK);
  }
  if (id === 'answer') {
    return params.prompt;
  }
  return '';
}

/**
 * What a node would compute now: its own setting and everything upstream of it. A node whose
 * signature has not changed since it last ran is served from its cache.
 */
export function signatureOf(links: Link[], params: Params, id: NodeId): string {
  const source = sourceOf(links, id);
  let upstream = '-';
  if (source !== null) {
    upstream = signatureOf(links, params, source);
  }
  return `${id}:${settingOf(id, params)}(${upstream})`;
}

/** How many items a node hands on: articles, chunks, vectors, passages, then one answer. */
function countOf(links: Link[], params: Params, id: NodeId): number {
  if (id === 'load') {
    return ARTICLE_COUNT;
  }
  if (id === 'split') {
    return Math.round(TOTAL_TOKENS / params.chunkSize);
  }
  if (id === 'answer') {
    return 1;
  }
  const source = sourceOf(links, id);
  let incoming = 0;
  if (source !== null) {
    incoming = countOf(links, params, source);
  }
  if (id === 'search') {
    return Math.min(params.topK, incoming);
  }
  return incoming;
}

function counted(count: number, word: string) {
  if (count === 1) {
    return `1 ${word}`;
  }
  return `${count} ${word}s`;
}

export type Result = {
  headline: string;
  lines: string[];
};

const SHOWN_PASSAGES = 2;

function dimensionsOf(params: Params) {
  const model = EMBED_MODELS.find(
    (candidate) => candidate.value === params.model
  );
  return model?.dimensions ?? 0;
}

/** The preview a node shows once it has run. The figures follow the settings and are illustrative. */
export function resultOf(links: Link[], params: Params, id: NodeId): Result {
  const count = countOf(links, params, id);
  if (id === 'load') {
    return {
      headline: counted(count, 'article'),
      lines: ['From the help center'],
    };
  }
  if (id === 'split') {
    return {
      headline: counted(count, 'chunk'),
      lines: [`About ${params.chunkSize} tokens each`],
    };
  }
  if (id === 'embed') {
    return {
      headline: counted(count, 'vector'),
      lines: [`${dimensionsOf(params)} dimensions`],
    };
  }
  if (id === 'search') {
    const shown = PASSAGES.slice(0, Math.min(count, SHOWN_PASSAGES));
    return {
      headline: counted(count, 'passage'),
      lines: shown.map((passage) => `${passage.title} · ${passage.score}`),
    };
  }
  const words = ANSWER_TEXT.split(' ');
  return { headline: counted(words.length, 'word'), lines: [ANSWER_TEXT] };
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import {
  EMBED_FAILURE,
  LINKS,
  nodeOf,
  NODES,
  PARAMS,
  type Link,
  type NodeId,
  type Params,
} from './data';
import {
  downstreamOf,
  missingInputOf,
  orderOf,
  refusalOf,
  resultOf,
  signatureOf,
  sourceOf,
  type Result,
} from './pipeline';

/**
 * How a wire came to be: there from the start, let go by a hand where it now sits, or made from a
 * menu. Only the last one draws itself, since the two others are already where they belong.
 */
export type Arrival = 'placed' | 'dropped' | 'drawn';

export type Wire = Link & {
  arrival: Arrival;
};

export type RunStatus =
  'idle' | 'running' | 'done' | 'cached' | 'failed' | 'skipped';

export type NodeRun = {
  status: RunStatus;
  /** What the node last computed. It stays, dimmed, once a setting upstream has changed. */
  result: Result | null;
  /** The signature of that result: the node is served from cache while it still matches. */
  signature: string | null;
  /** Why it failed or was skipped. */
  message: string | null;
};

/** A wire held out of an output: by a pointer, or by the demonstration. `to` is the node it is over. */
export type Wiring = {
  from: NodeId;
  to: NodeId | null;
};

export type Refused = {
  id: number;
  from: NodeId;
  to: NodeId;
  reason: string;
};

/** The node a run has reached. The token tells one run from the next, so a late timer changes nothing. */
export type Run = {
  order: NodeId[];
  at: number;
  token: number;
};

export type GraphState = {
  wires: Wire[];
  params: Params;
  runs: Record<NodeId, NodeRun>;
  run: Run | null;
  runCount: number;
  /** Embed fails the first time it runs, then works. */
  hasEmbedFailed: boolean;
  wiring: Wiring | null;
  refused: Refused | null;
  refusalCount: number;
  /** The last change, said to screen readers. */
  notice: string;
};

export type GraphAction =
  | { type: 'wireStarted'; from: NodeId }
  | { type: 'wireAimed'; to: NodeId | null }
  | { type: 'wireDropped' }
  | { type: 'wireCancelled' }
  | { type: 'connected'; from: NodeId; to: NodeId }
  | { type: 'disconnected'; to: NodeId }
  | { type: 'refusalCleared'; id: number }
  | { type: 'paramsChanged'; params: Partial<Params> }
  | { type: 'ran' }
  | { type: 'phaseEnded'; token: number }
  | { type: 'waited' };

type Beat = SessionStep<GraphState, GraphAction>;

/** A node served from cache shows it for this long before the run moves on. */
export const CACHED_MS = 320;

const NEVER_RUN: NodeRun = {
  status: 'idle',
  result: null,
  signature: null,
  message: null,
};

function placed(link: Link): Wire {
  return { ...link, arrival: 'placed' };
}

/** The documents were loaded before the page opened, so the first run finds them in cache. */
const LOADED: NodeRun = {
  status: 'idle',
  result: resultOf(LINKS, PARAMS, 'load'),
  signature: signatureOf(LINKS, PARAMS, 'load'),
  message: null,
};

export const INITIAL: GraphState = {
  wires: LINKS.map(placed),
  params: PARAMS,
  runs: {
    load: LOADED,
    split: NEVER_RUN,
    embed: NEVER_RUN,
    search: NEVER_RUN,
    answer: NEVER_RUN,
  },
  run: null,
  runCount: 0,
  hasEmbedFailed: false,
  wiring: null,
  refused: null,
  refusalCount: 0,
  notice: '',
};

/** The node of each setting: changing it makes that node, and what it feeds, out of date. */
const NODE_OF_PARAM: Record<keyof Params, NodeId> = {
  chunkSize: 'split',
  model: 'embed',
  topK: 'search',
  prompt: 'answer',
};

const PARAM_KEYS: (keyof Params)[] = ['chunkSize', 'model', 'topK', 'prompt'];

export function isRunning(state: GraphState) {
  return state.run !== null;
}

/** The node the run is on, with how long it stays there. */
export function phaseOf(state: GraphState) {
  const run = state.run;
  if (!run) {
    return null;
  }
  const id = run.order[run.at];
  const isCached = state.runs[id].status === 'cached';
  if (isCached) {
    return { id, token: run.token, ms: CACHED_MS };
  }
  return { id, token: run.token, ms: nodeOf(id).runMs };
}

function withRun(
  state: GraphState,
  id: NodeId,
  patch: Partial<NodeRun>
): GraphState {
  const next = { ...state.runs[id], ...patch };
  return { ...state, runs: { ...state.runs, [id]: next } };
}

/** A change makes a node and everything it feeds wait for the next run. Their last results stay. */
function staleFrom(state: GraphState, id: NodeId): GraphState {
  let next = state;
  for (const reached of downstreamOf(state.wires, id)) {
    next = withRun(next, reached, { status: 'idle', message: null });
  }
  return next;
}

function refusedWith(
  state: GraphState,
  from: NodeId,
  to: NodeId,
  reason: string
): GraphState {
  const id = state.refusalCount + 1;
  return {
    ...state,
    refused: { id, from, to, reason },
    refusalCount: id,
    notice: reason,
  };
}

function linked(
  state: GraphState,
  from: NodeId,
  to: NodeId,
  arrival: Arrival
): GraphState {
  if (isRunning(state)) {
    return state;
  }
  const reason = refusalOf(state.wires, from, to);
  if (reason !== null) {
    return refusedWith(state, from, to, reason);
  }
  const isSame = sourceOf(state.wires, to) === from;
  if (isSame) {
    return state;
  }
  const others = state.wires.filter((wire) => wire.to !== to);
  const rewired = { ...state, wires: [...others, { from, to, arrival }] };
  const next = staleFrom(rewired, to);
  const source = nodeOf(from).title;
  const target = nodeOf(to).title;
  return { ...next, refused: null, notice: `${source} now feeds ${target}` };
}

function wireStarted(state: GraphState, from: NodeId): GraphState {
  if (isRunning(state)) {
    return state;
  }
  return { ...state, wiring: { from, to: null }, refused: null };
}

function wireAimed(state: GraphState, to: NodeId | null): GraphState {
  const wiring = state.wiring;
  if (!wiring || wiring.to === to) {
    return state;
  }
  return { ...state, wiring: { ...wiring, to } };
}

function wireDropped(state: GraphState): GraphState {
  const wiring = state.wiring;
  if (!wiring) {
    return state;
  }
  const released = { ...state, wiring: null };
  if (wiring.to === null) {
    return released;
  }
  return linked(released, wiring.from, wiring.to, 'dropped');
}

function disconnected(state: GraphState, to: NodeId): GraphState {
  const wires = state.wires.filter((wire) => wire.to !== to);
  const hasChanged = wires.length !== state.wires.length;
  if (isRunning(state) || !hasChanged) {
    return state;
  }
  const next = staleFrom({ ...state, wires }, to);
  return { ...next, notice: `Nothing feeds ${nodeOf(to).title} now` };
}

function paramsChanged(
  state: GraphState,
  changes: Partial<Params>
): GraphState {
  if (isRunning(state)) {
    return state;
  }
  const params = { ...state.params, ...changes };
  let next: GraphState = { ...state, params, notice: '' };
  for (const key of PARAM_KEYS) {
    const hasChanged = params[key] !== state.params[key];
    if (hasChanged) {
      next = staleFrom(next, NODE_OF_PARAM[key]);
    }
  }
  return next;
}

/** A node cannot run without its input, nor after a node that failed or was itself skipped. */
function blockedReasonOf(state: GraphState, id: NodeId) {
  const missing = missingInputOf(state.wires, id);
  if (missing !== null) {
    return missing;
  }
  const source = sourceOf(state.wires, id);
  if (source === null) {
    return null;
  }
  const status = state.runs[source].status;
  const isHeldUp = status === 'failed' || status === 'skipped';
  if (isHeldUp) {
    return `Waiting on ${nodeOf(source).title}`;
  }
  return null;
}

function startStatusOf(isCached: boolean): RunStatus {
  if (isCached) {
    return 'cached';
  }
  return 'running';
}

function summaryOf(state: GraphState) {
  const failed = NODES.find((node) => state.runs[node.id].status === 'failed');
  if (failed) {
    const message = state.runs[failed.id].message;
    return `${failed.title} failed: ${message}. Retry is available`;
  }
  return 'The run is finished';
}

/**
 * Moves the run to the next node that takes time: one that runs, or one served from cache. The
 * nodes that cannot run are marked skipped on the way. Past the last node the run is over.
 */
function advanced(state: GraphState, run: Run, from: number): GraphState {
  let next = state;
  for (let at = from; at < run.order.length; at += 1) {
    const id = run.order[at];
    const reason = blockedReasonOf(next, id);
    if (reason === null) {
      const signature = signatureOf(next.wires, next.params, id);
      const last = next.runs[id];
      const isCached = last.result !== null && last.signature === signature;
      const started = withRun(next, id, { status: startStatusOf(isCached) });
      return { ...started, run: { ...run, at } };
    }
    next = withRun(next, id, { status: 'skipped', message: reason });
  }
  return { ...next, run: null, notice: summaryOf(next) };
}

function ran(state: GraphState): GraphState {
  if (isRunning(state)) {
    return state;
  }
  let next: GraphState = { ...state, wiring: null, refused: null };
  for (const node of NODES) {
    next = withRun(next, node.id, { status: 'idle', message: null });
  }
  const token = state.runCount + 1;
  const run = { order: orderOf(next.wires), at: 0, token };
  return advanced({ ...next, runCount: token, notice: 'Run started' }, run, 0);
}

function finished(state: GraphState, id: NodeId): GraphState {
  const failsNow = id === 'embed' && !state.hasEmbedFailed;
  if (failsNow) {
    const failed = withRun(state, id, {
      status: 'failed',
      message: EMBED_FAILURE,
    });
    return { ...failed, hasEmbedFailed: true };
  }
  return withRun(state, id, {
    status: 'done',
    result: resultOf(state.wires, state.params, id),
    signature: signatureOf(state.wires, state.params, id),
    message: null,
  });
}

function phaseEnded(state: GraphState, token: number): GraphState {
  const run = state.run;
  if (!run || run.token !== token) {
    return state;
  }
  const id = run.order[run.at];
  let next = state;
  if (state.runs[id].status === 'running') {
    next = finished(state, id);
  }
  return advanced(next, run, run.at + 1);
}

function refusalCleared(state: GraphState, id: number): GraphState {
  if (state.refused?.id !== id) {
    return state;
  }
  return { ...state, refused: null };
}

export function reducer(state: GraphState, action: GraphAction): GraphState {
  switch (action.type) {
    case 'wireStarted':
      return wireStarted(state, action.from);
    case 'wireAimed':
      return wireAimed(state, action.to);
    case 'wireDropped':
      return wireDropped(state);
    case 'wireCancelled':
      return { ...state, wiring: null };
    case 'connected':
      return linked(state, action.from, action.to, 'drawn');
    case 'disconnected':
      return disconnected(state, action.to);
    case 'refusalCleared':
      return refusalCleared(state, action.id);
    case 'paramsChanged':
      return paramsChanged(state, action.params);
    case 'ran':
      return ran(state);
    case 'phaseEnded':
      return phaseEnded(state, action.token);
    case 'waited':
      return state;
  }
}

export function hasFailure(state: GraphState) {
  return NODES.some((node) => state.runs[node.id].status === 'failed');
}

function hasNoFailure(state: GraphState) {
  return !hasFailure(state);
}

/** Runs to its end at once: what the timers do one node after the other. */
function settled(state: GraphState) {
  let next = state;
  while (next.run) {
    next = phaseEnded(next, next.run.token);
  }
  return next;
}

function holdOutSteps(after: number, from: NodeId, to: NodeId): Beat[] {
  return [
    {
      after,
      by: 'demo',
      press: `out-${from}`,
      action: { type: 'wireStarted', from },
    },
    { after: 520, by: 'demo', action: { type: 'wireAimed', to } },
    { after: 850, by: 'demo', action: { type: 'wireDropped' } },
  ];
}

/** Chunks into a port that takes Vectors: the wire is refused and says why. */
const REFUSED = holdOutSteps(1500, 'split', 'search');

const CONNECTED = holdOutSteps(2700, 'embed', 'search');

const RUN: Beat = {
  after: 1300,
  by: 'demo',
  press: 'run',
  action: { type: 'ran' },
};

/**
 * A step of the system that only waits. The session holds it while a run is going, so what follows
 * comes once the run is over, however long it took.
 */
function runOver(after: number): Beat {
  return { after, action: { type: 'waited' } };
}

/** A failure that waits on a person is retried by the demonstration after this long. */
const DECIDE_AFTER_MS = 2500;

const RETRY: Beat = {
  after: DECIDE_AFTER_MS,
  by: 'person',
  press: 'retry',
  action: { type: 'ran' },
  isAnswered: hasNoFailure,
};

export const SCRIPT: Beat[] = [
  ...REFUSED,
  ...CONNECTED,
  RUN,
  runOver(200),
  RETRY,
  runOver(600),
];

/**
 * Under reduced motion the editor rests on the second run: every wire in place, two nodes served
 * from cache, three that ran, each with its preview.
 */
function restingOf() {
  let state = INITIAL;
  for (const beat of CONNECTED) {
    state = reducer(state, beat.action);
  }
  const firstRun = settled(ran(state));
  const secondRun = settled(ran(firstRun));
  return { ...secondRun, wires: secondRun.wires.map(placed), notice: '' };
}

export const RESTING = restingOf();

export const LOOP_AFTER_MS = 3800;

