export function nodeOf(id: NodeId) {
  const node = NODES.find((candidate) => candidate.id === id);
  return node ?? NODES[0];
}

export function nodeIdOf(value: string | undefined | null) {
  const node = NODES.find((candidate) => candidate.id === value);
  return node?.id ?? null;
}

